<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\ProductRequest; use App\Http\Resources\ProductResource; use App\Models\Product; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
class ProductController extends Controller { public function index(Request $r): AnonymousResourceCollection { $query=Product::with('category')->when($r->search,fn($q,$s)=>$q->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('description','like',"%$s%")))->when($r->category_id,fn($q,$id)=>$q->where('category_id',$id))->when(!$r->user()?->isAdmin(),fn($q)=>$q->where('is_active',true))->latest(); return ProductResource::collection($query->paginate($r->integer('per_page',9))->withQueryString()); } public function store(ProductRequest $r): JsonResponse { $p=Product::create($r->validated()); return response()->json(['data'=>new ProductResource($p->load('category'))],201); } public function show(Product $product): ProductResource { abort_if(!$product->is_active && !request()->user()?->isAdmin(),404); return new ProductResource($product->load('category')); } public function update(ProductRequest $r,Product $product): ProductResource { $product->update($r->validated()); return new ProductResource($product->load('category')); } public function destroy(Product $product): JsonResponse { if($product->quotationRequestItems()->exists()) return response()->json(['message'=>'A product used in quotation requests cannot be deleted.'],422); $product->delete(); return response()->json(null,204); } }
